-- Saved reports, scheduled delivery, private output storage, and export auditing.
create table public.report_definitions(id uuid primary key default gen_random_uuid(),name text not null,report_type text not null,filters jsonb not null default '{}',columns jsonb not null default '[]',owner_id uuid not null references public.users(id),shared boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.report_schedules(id uuid primary key default gen_random_uuid(),definition_id uuid not null references public.report_definitions(id) on delete cascade,frequency text not null check(frequency in ('DAILY','WEEKLY','MONTHLY','QUARTERLY')),timezone text not null default 'Africa/Lagos',recipients text[] not null default '{}',format text not null check(format in ('PDF','EXCEL','CSV')),next_run_at timestamptz not null,active boolean not null default true,created_by uuid not null references public.users(id),created_at timestamptz not null default now());
alter table public.report_exports add column if not exists definition_id uuid references public.report_definitions(id);
alter table public.report_exports add column if not exists expires_at timestamptz;
alter table public.report_exports add column if not exists error_message text;
alter table public.report_definitions enable row level security;alter table public.report_schedules enable row level security;
create policy "owners view report definitions" on public.report_definitions for select to authenticated using(owner_id=auth.uid() or shared or public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create policy "owners manage report definitions" on public.report_definitions for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "owners view report schedules" on public.report_schedules for select to authenticated using(created_by=auth.uid() or public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create policy "owners manage report schedules" on public.report_schedules for all to authenticated using(created_by=auth.uid()) with check(created_by=auth.uid());
create or replace function public.audit_report_export() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into audit_logs(user_id,action,entity_type,entity_id,new_data) values(auth.uid(),'REQUEST_REPORT_EXPORT','report_export',new.id::text,jsonb_build_object('type',new.report_type,'format',new.format,'date_from',new.date_from,'date_to',new.date_to));return new;end $$;
drop trigger if exists report_export_audit on public.report_exports;create trigger report_export_audit after insert on public.report_exports for each row execute function public.audit_report_export();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('report-exports','report-exports',false,20971520,array['application/pdf','text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict(id) do update set public=false,file_size_limit=20971520;
create policy "owners download report exports" on storage.objects for select to authenticated using(bucket_id='report-exports' and ((storage.foldername(name))[1]=auth.uid()::text or public.current_role() in ('SUPER_ADMIN','HR_MANAGER')));
comment on table public.report_schedules is 'A trusted worker claims due schedules, applies the creator RLS scope, writes private output, and advances next_run_at.';
